phase1.code:
fn main() {
    // ---- Creating vectors ----
    let mut v1: Vec<i32> = Vec::new();
    let v2 = vec![1, 2, 3, 4, 5];
    let v3 = vec![0; 10];  // 10 zeros

    // ---- Adding elements ----
    v1.push(10);
    v1.push(20);
    v1.push(30);

    // ---- Accessing elements ----
    let first = &v2[0];  // Panics if out of bounds
    let second = v2.get(1);  // Returns Option

    println!("v1: {:?}", v1);
    println!("v2: {:?}", v2);
    println!("v3: {:?}", v3);
    println!("first: {}, second: {:?}", first, second);

    // ---- Iterating ----
    println!("\n=== Iterating ===");
    for i in &v1 {
        println!("v1 element: {}", i);
    }

    // ---- Mutating while iterating ----
    for i in &mut v1 {
        *i *= 2;
    }
    println!("After doubling: {:?}", v1);

    // ---- Removing elements ----
    let last = v1.pop();  // Removes and returns last
    println!("Popped: {:?}, v1: {:?}", last, v1);

    // ---- Inserting elements ----
    v1.insert(1, 15);  // Insert at index 1
    println!("After insert: {:?}", v1);

    // ---- Removing by index ----
    let removed = v1.remove(2);
    println!("Removed: {}, v1: {:?}", removed, v1);

    // ---- Vector of structs ----
    #[derive(Debug)]
    struct Player {
        name: String,
        health: i32,
    }

    let mut players = vec![
        Player { name: String::from("Hero"), health: 100 },
        Player { name: String::from("Aragorn"), health: 120 },
    ];

    players.push(Player { name: String::from("Gandalf"), health: 80 });

    println!("\nPlayers: {:#?}", players);

    // ---- Vector with capacity ----
    let mut with_capacity: Vec<i32> = Vec::with_capacity(10);
    println!("Capacity: {}, Length: {}", with_capacity.capacity(), with_capacity.len());

    for i in 0..5 {
        with_capacity.push(i);
    }
    println!("After push: Capacity: {}, Length: {}", with_capacity.capacity(), with_capacity.len());

    // ---- Vector methods ----
    let numbers = vec![5, 2, 8, 1, 9, 3];

    // Contains
    println!("Contains 5? {}", numbers.contains(&5));

    // Sort
    let mut sorted = numbers.clone();
    sorted.sort();
    println!("Sorted: {:?}", sorted);

    // Reverse
    let mut reversed = numbers.clone();
    reversed.reverse();
    println!("Reversed: {:?}", reversed);

    // Join
    let words = vec!["Hello", "world", "from", "Rust"];
    let joined = words.join(" ");
    println!("Joined: {}", joined);
}

phase2.brokenCode:
fn main() {
    let v = vec![1, 2, 3];
    let first = v[10];  // Index out of bounds!
    println!("first: {}", first);
}

phase2.explanation:
Accessing an out-of-bounds index with `[]` panics.

**The fix:**
```rust
let first = v.get(10);  // Returns None
if let Some(value) = first {
    println!("first: {}", value);
} else {
    println!("Index out of bounds");
}
```

**Rust-chan says:**
"Use `get()` for safe access. It returns Option, not a panic."
